 "content": "def transform(grid):
    """Shift each 4 one row downward; the lowest 4 above the 2-bar casts an upward V."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    marks = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    for r, c in marks:
        out[r][c] = 0
    for r, c in marks:
        if r + 1 < h:
            out[r + 1][c] = 4
    if divider is not None:
        above = [(r, c) for r, c in marks if r < divider]
        if above:
            r, c = max(above)
            # The bottommost marker above the divider shifts down one row;
            # extend its two upward diagonals until the top or a side edge.
            base_r = r + 1
            for d in range(1, base_r + 1):
                rr = base_r - d
                for cc in (c - d, c + d):
                    if 0 <= rr < divider and 0 <= cc < w:
                        out[rr][cc] = 4
    return out
